    // Implement encoding for potentially dangerous characters like double quotes and backslashes
    // to prevent malformed output when serialized (e.g., in Python dict format) and potential injection issues.
    // This addresses the "Encoding Fallback" recommendation from previous feedback.
    for (size_t pos = 0; (pos = sanitized_content.find('\\', pos)) != std::string::npos; pos += 2) {
