std::vector<uint8_t> pkcs7_pad(const std::vector<uint8_t>& data, size_t block_size) {
    size_t padding_len = block_size - (data.size() % block_size);
    std::vector<uint8_t> padded = data;
    padded.insert(padded.end(), padding_len, static_cast<uint8_t>(padding_len));
    return padded;
}

/**
Encrypt the data with the key using AES and CBC mode.
The provided key bytes is long enough (>= 64 bytes). Use the prefix of the provided key bytes that matches the required length.
Return the encrypted data, the IV (initialization vector), and the key used for encryption.

@param key The bytes to generate the encryption key
@param data The data to encrypt
@return tuple containing: {encrypted data, IV, key used for encryption}
*/
std::tuple<std::vector<uint8_t>, std::vector<uint8_t>, std::vector<uint8_t>>
encrypt_data(const std::vector<uint8_t>& key, const std::vector<uint8_t>& data) {
    const size_t BLOCK_SIZE = AES_BLOCK_SIZE; // 16 bytes, using a different name to avoid macro conflict
    const size_t AES_KEY_LENGTH = 32; // For AES-256, 32 bytes (256 bits)

    // 1. Derive encryption key
    if (key.size() < AES_KEY_LENGTH) {
        throw std::runtime_error("Provided key is too short for AES-256 encryption.");
    }
    std::vector<uint8_t> actual_key(key.begin(), key.begin() + AES_KEY_LENGTH);

    // 2. Initialize AES key structure
    AES_KEY aes_key_struct;
    // AES_set_encrypt_key expects key length in bits
    if (AES_set_encrypt_key(actual_key.data(), AES_KEY_LENGTH * 8, &aes_key_struct) < 0) {
        throw std::runtime_error("Failed to set AES encryption key.");
    }

    // 3. Generate IV
    std::vector<uint8_t> iv(BLOCK_SIZE);
    if (RAND_bytes(iv.data(), iv.size()) != 1) {
        throw std::runtime_error("Failed to generate random IV.");
    }

    // 4. Pad data
    std::vector<uint8_t> padded_data = pkcs7_pad(data, BLOCK_SIZE);

    // 5. Prepare output buffer
    std::vector<uint8_t> encrypted_data(padded_data.size());

    // 6. Perform encryption
    // AES_cbc_encrypt modifies the IV in place, so we need a copy
    std::vector<uint8_t> iv_copy = iv; 
    AES_cbc_encrypt(padded_data.data(), encrypted_data.data(), padded_data.size(), &aes_key_struct, iv_copy.data(), AES_ENCRYPT);

    // 7. Return results
    return std::make_tuple(encrypted_data, iv, actual_key);
}

